import{_ as r,c as t,o as a,ag as o}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"Practice: How do you start a REACT project from scratch?","description":"","frontmatter":{},"headers":[],"relativePath":"practice/frontend/react/How_do_you_start_a_REACT_project_from_scratch.md","filePath":"practice/frontend/react/How_do_you_start_a_REACT_project_from_scratch.md"}'),c={name:"practice/frontend/react/How_do_you_start_a_REACT_project_from_scratch.md"};function n(s,e,i,l,d,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="practice-how-do-you-start-a-react-project-from-scratch" tabindex="-1">Practice: How do you start a REACT project from scratch? <a class="header-anchor" href="#practice-how-do-you-start-a-react-project-from-scratch" aria-label="Permalink to “Practice: How do you start a REACT project from scratch?”">​</a></h1><p><strong>Status: outstanding learner practice.</strong> Author checks do not complete these requirements.</p><p>Prerequisite: study the <a href="./../../../senior_growth/React/How_do_you_start_a_REACT_project_from_scratch.html">worked lesson</a> and its linked foundations. Apply these focused cases to <a href="./../../frontend-project.html">P-328/P-329/P-330</a>; retain only the cases relevant to the chosen increment.</p><h2 id="scope-and-observable-criteria" tabindex="-1">Scope and observable criteria <a class="header-anchor" href="#scope-and-observable-criteria" aria-label="Permalink to “Scope and observable criteria”">​</a></h2><p><strong>Exercise acceptance:</strong> create a pinned client app, render an accessible labeled form and one lazy route, then run typecheck/lint/tests/build/preview as configured. Test deep-link refresh, invalid route, missing root, asset base path, chunk loading, failed API and no-JS behavior; map one production stack trace through the chosen source-map policy. Record versions/lockfile/commands/results and keep the app buildable in small increments. No React/Webpack application install/build was performed in this notes repository. Its docs build only checks the study material.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to “Evidence”">​</a></h2><p>Record source revision, runtime/browser versions, expected versus observed result, one reproduced failure, correction and retest. Include exact commands or input sequence and artifacts. Mark unperformed keyboard, screen-reader, zoom, device and integration checks explicitly. Never record a supplied example as your completed practice.</p><h2 id="reproducible-setup-and-production-acceptance" tabindex="-1">Reproducible setup and production acceptance <a class="header-anchor" href="#reproducible-setup-and-production-acceptance" aria-label="Permalink to “Reproducible setup and production acceptance”">​</a></h2><p>Applicable React19 client root API: createRoot; hydrateRoot for existing server-rendered React HTML. ReactDOM.render was removed in React19. The automatic JSX transform is required by current React; explicit Babel runtime configuration above avoids relying on a changing preset default. These instructions are a setup lesson, not changes to this repository&#39;s VitePress scripts.</p><p>The manual Webpack/Babel path is an alternative learning lab. Pin compatible Webpack5/Babel/plugin versions and lockfile; choose consistent module config extensions. Babel transpilation does not typecheck TypeScript. If adding TS, configure parser/loader plus a separate tsc --noEmit check and correct TS/browser/module targets. Resolve extension/alias settings consistently across bundler, typechecker and tests; an editor alias alone does not change runtime resolution. Source maps improve debugging but must not expose secrets/private source unintentionally in a public deployment.</p><p>Use the scaffold&#39;s current scripts/config rather than installing unrelated tools blindly. Add accessible base HTML, CSS ownership, one meaningful route, error/loading behavior and a server boundary for secrets. A client environment prefix is public configuration, not secret storage. Avoid installing every store/form/styling library in a starter: local state, CSS Modules, native fetch and an explicit router/query requirement are enough to begin.</p><p>Official references checked2026-10-21: <a href="https://react.dev/blog/2025/02/14/sunsetting-create-react-app" target="_blank" rel="noreferrer">CRA deprecation</a>, <a href="https://react.dev/blog/2024/04/25/react-19-upgrade-guide" target="_blank" rel="noreferrer">React19 removed APIs/JSX</a>, <a href="https://vite.dev/guide/" target="_blank" rel="noreferrer">Vite scaffold</a>, <a href="https://babeljs.io/docs/babel-preset-react" target="_blank" rel="noreferrer">Babel React preset</a>, <a href="https://webpack.js.org/guides/typescript/" target="_blank" rel="noreferrer">Webpack TypeScript</a>.</p><p>For executable compiler configuration, alias failure drills, NodeNext output and production source-map handling, complete the <a href="./../../../senior_growth/React/build_tools.html#worked-lab-typechecking-host-resolution-and-private-source-maps">worked build and resolution lab</a>. This supplies the concrete configuration beyond the setup checklist above.</p>',13)])])}const b=r(c,[["render",n]]);export{h as __pageData,b as default};
